"use strict";(self.webpackChunkspa_template=self.webpackChunkspa_template||[]).push([[955],{2955:e=>{e.exports=JSON.parse('{"created":"2016-04-09T13:01:00","modified":"2016-04-09T13:01:00","id":1028,"title":"Created addEventlistener-with-dispatch polyfill for IE8","article":"<p>As developers sometimes we need to be able to support IE8, although thankfully that is getting less these days. I needed a polyfill for <code>document.addEventListener</code> that also supported <code>dispatchEvent</code>. I could not find a complete solution that was tested. </p>\\n<p>So I decided to develop <strong>addeventlistener-with-dispatch</strong>.</p>\\n<p>It is available on <a href=\\"https://www.npmjs.com/package/addeventlistener-with-dispatch\\">npm</a> and <a href=\\"http://bower.io/search/?q=addeventlistener-with-dispatch\\">bower</a> as well as having the source code, along with a readme on how to use it on <a href=\\"http://bower.io/search/?q=addeventlistener-with-dispatch\\">GitHub</a>. Either take a copy from the dist folder on GitHub or install it using one of the commands below:</p>\\n<pre><code class=\\"hljs language-bash\\">npm install addeventlistener-with-dispatch --save\\n\\nbower install addeventlistener-with-dispatch --save</code></pre>\\n","showInResults":true,"tags":["javascript","polyfill"]}')}}]);